css:
:where(.wtyg-map-tipping_points) .tp{font:12.5px/1.5 system-ui,sans-serif;color:#DCE6EA}
:where(.wtyg-map-tipping_points) .tp h2{font-size:16px;margin:0 0 2px;color:#E8F1F4}
:where(.wtyg-map-tipping_points) .tp h4{font-size:12.5px;margin:10px 0 3px;color:#BFD8E0}
:where(.wtyg-map-tipping_points) .tp-sub{color:#93A9B0;margin-bottom:6px}
:where(.wtyg-map-tipping_points) .tp-flag{border-left:3px solid #8FD6E8;padding:2px 8px;margin:4px 0 6px}
:where(.wtyg-map-tipping_points) .tp-big{font-size:13.5px;font-weight:600;margin:2px 0}
:where(.wtyg-map-tipping_points) .tp-cap2{font-weight:600;margin:10px 0 3px;color:#BFD8E0}
:where(.wtyg-map-tipping_points) .tp-note,:where(.wtyg-map-tipping_points) .tp-foot,:where(.wtyg-map-tipping_points) .tp-cap{color:#93A9B0;font-size:11.5px}
:where(.wtyg-map-tipping_points) .tp-foot{margin-top:8px}
:where(.wtyg-map-tipping_points) .tp-scroll{overflow:auto;max-width:100%}
:where(.wtyg-map-tipping_points) table{border-collapse:collapse;font-size:11.5px;margin:2px 0}
:where(.wtyg-map-tipping_points) th,:where(.wtyg-map-tipping_points) td{border:1px solid #24404F;padding:2px 5px;vertical-align:top;text-align:left}
:where(.wtyg-map-tipping_points) th{color:#BFD8E0;font-weight:600}
:where(.wtyg-map-tipping_points) details{margin:8px 0}
:where(.wtyg-map-tipping_points) summary{cursor:pointer;color:#8FC3D6}
:where(.wtyg-map-tipping_points) .tp-text{max-height:360px;overflow:auto;padding-right:6px}
:where(.wtyg-map-tipping_points) .tp-mine{border-left:3px solid #8FD6E8;padding-left:6px}
:where(.wtyg-map-tipping_points) img{max-width:100%;height:auto;display:block;margin-top:6px}
:where(.wtyg-map-tipping_points) a{color:#8FC3D6}
:where(.wtyg-map-tipping_points) .tp-pick{display:inline-block;margin:0 4px 4px 0;padding:1px 6px;border:1px solid #24404F;border-radius:3px;cursor:pointer;color:#BFD8E0}
.tp-pop .maplibregl-popup-content{background:#0F1C26;color:#DCE6EA;max-height:540px;overflow:auto}
